__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"ARTICLES",{enumerable:!0,get:function(){return s}});const s=[{id:'phases',category:'Cycle',title:'Les 4 phases du cycle, simplement',minutes:4,body:["Un cycle commence le premier jour des r\xe8gles et se termine la veille des suivantes. Il dure en moyenne 28 jours, mais tout cycle entre 21 et 35 jours est consid\xe9r\xe9 comme normal chez l'adulte.","R\xe8gles (jours 1 \xe0 5 environ) : la muqueuse ut\xe9rine s'\xe9limine. Les hormones sont au plus bas, la fatigue est fr\xe9quente.","Phase folliculaire : un follicule m\xfbrit dans l'ovaire sous l'effet de la FSH et les \u0153strog\xe8nes augmentent. Beaucoup se sentent plus \xe9nergiques.","Ovulation : un pic de LH lib\xe8re l'ovule, qui vit 12 \xe0 24 heures. Les spermatozo\xefdes pouvant survivre jusqu'\xe0 5 jours, la fen\xeatre fertile couvre environ 6 jours.","Phase lut\xe9ale : la progest\xe9rone pr\xe9pare l'ut\xe9rus. Sa dur\xe9e est assez stable d'un cycle \xe0 l'autre (10 \xe0 16 jours). Sans f\xe9condation, les hormones chutent et les r\xe8gles arrivent."]},{id:'fertile-window',category:'Fertilit\xe9',title:'Rep\xe9rer sa fen\xeatre de fertilit\xe9',minutes:5,body:["Le calendrier seul donne une estimation. Pour plus de pr\xe9cision, combinez plusieurs signes : c'est le principe de la m\xe9thode symptothermique.","La glaire cervicale devient claire, glissante et \xe9lastique (comme du blanc d'\u0153uf) dans les jours qui pr\xe9c\xe8dent l'ovulation.","Les tests d'ovulation d\xe9tectent le pic de LH, qui pr\xe9c\xe8de l'ovulation de 24 \xe0 36 heures. Notez-les dans Lun\xe9a : l'application s'en sert pour confirmer l'ovulation.","La temp\xe9rature basale monte de 0,2 \xe0 0,5 \xb0C apr\xe8s l'ovulation et reste haute jusqu'aux r\xe8gles. Prenez-la au r\xe9veil, avant de vous lever, \xe0 heure fixe.","Important : aucune application ne constitue \xe0 elle seule une m\xe9thode de contraception fiable."]},{id:'pms',category:'Bien-\xeatre',title:'Syndrome pr\xe9menstruel : ce qui aide vraiment',minutes:4,body:["Le SPM regroupe des sympt\xf4mes physiques et \xe9motionnels qui apparaissent pendant la phase lut\xe9ale et disparaissent avec les r\xe8gles.","L'activit\xe9 physique r\xe9guli\xe8re, un sommeil suffisant et la r\xe9duction de la caf\xe9ine, de l'alcool et du sel am\xe9liorent souvent les sympt\xf4mes.","Noter vos sympt\xf4mes plusieurs cycles de suite permet de v\xe9rifier qu'ils suivent bien le cycle. C'est aussi une information pr\xe9cieuse pour un m\xe9decin.","Si l'humeur devient tr\xe8s sombre ou que la vie quotidienne est perturb\xe9e, parlez-en \xe0 un professionnel : un trouble dysphorique pr\xe9menstruel (TDPM) se soigne."]},{id:'irregular',category:'Sant\xe9',title:'Cycles irr\xe9guliers : quand consulter ?',minutes:4,body:["Une variation de quelques jours d'un cycle \xe0 l'autre est normale. Le stress, le voyage, une maladie ou un changement de poids peuvent d\xe9caler l'ovulation.","Consultez si vos cycles font r\xe9guli\xe8rement moins de 21 jours ou plus de 35 jours, si les r\xe8gles durent plus de 7 jours, si vous n'avez pas de r\xe8gles pendant 3 mois, ou en cas de douleurs intenses.","Le syndrome des ovaires polykystiques (SOPK), les troubles de la thyro\xefde ou l'endom\xe9triose font partie des causes \xe0 explorer. Le rapport de Lun\xe9a peut servir de base \xe0 la consultation."]},{id:'endometriosis',category:'Sant\xe9',title:"Endom\xe9triose : les signes \xe0 conna\xeetre",minutes:5,body:["L'endom\xe9triose touche environ une femme sur dix. Le diagnostic prend souvent plusieurs ann\xe9es car les douleurs de r\xe8gles sont banalis\xe9es.","Signes d'alerte : r\xe8gles tr\xe8s douloureuses qui r\xe9sistent aux antalgiques courants, douleurs pendant les rapports, douleurs en allant \xe0 la selle ou en urinant pendant les r\xe8gles, difficult\xe9s \xe0 concevoir.","Noter l'intensit\xe9 de vos douleurs dans le journal permet de montrer leur \xe9volution au m\xe9decin."]},{id:'first-trimester',category:'Grossesse',title:'Premier trimestre : les essentiels',minutes:5,body:["L'acide folique est recommand\xe9 d\xe8s le projet de grossesse et jusqu'\xe0 la fin du premier trimestre.","\xc9vitez l'alcool, le tabac et certains aliments (fromages au lait cru, viande et poisson crus ou peu cuits) et lavez bien les fruits et l\xe9gumes.","Naus\xe9es et fatigue sont fr\xe9quentes. Fractionnez les repas et reposez-vous d\xe8s que possible.","Consultez sans attendre en cas de saignements abondants, de douleurs fortes ou de fi\xe8vre."]},{id:'sleep',category:'Bien-\xeatre',title:'Sommeil et cycle',minutes:3,body:["La hausse de temp\xe9rature de la phase lut\xe9ale peut rendre le sommeil plus l\xe9ger en fin de cycle.","Une chambre fra\xeeche, des horaires r\xe9guliers et moins d'\xe9crans le soir aident particuli\xe8rement les jours pr\xe9c\xe9dant les r\xe8gles.","Notez vos heures de sommeil dans Lun\xe9a pour voir si elles varient selon vos phases."]}]},785,[]);
